#!/usr/bin/env node
// Generated by stencil-mcp-output-target. Do not edit: it is rewritten by every production build.
//
// Registers this library's MCP server with the MCP clients of the project it is run in. It adds
// one entry to each client's project config file and leaves the rest of the file as it was. It
// writes only under the current directory, has no dependencies and makes no network request.
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { isDeepStrictEqual, parseArgs } from 'node:util';

// The output target fills this line in: the server's name, the package that ships it, and its bin.
const LIBRARY = { name: 'components', package: 'components', bin: 'components-mcp' };

/**
 * A client's project config: the file, the key its servers sit under, what an entry carries
 * beside the command, and the paths that show a project uses the client.
 */
const CLIENTS = {
  claude: { label: 'Claude Code', file: '.mcp.json', key: 'mcpServers', extra: {}, signs: ['.mcp.json', '.claude', 'CLAUDE.md'] },
  cursor: { label: 'Cursor', file: '.cursor/mcp.json', key: 'mcpServers', extra: {}, signs: ['.cursor'] },
  vscode: { label: 'VS Code', file: '.vscode/mcp.json', key: 'servers', extra: { type: 'stdio' }, signs: ['.vscode'] },
  gemini: { label: 'Gemini CLI', file: '.gemini/settings.json', key: 'mcpServers', extra: {}, signs: ['.gemini', 'GEMINI.md'] },
};

const NAMES = Object.keys(CLIENTS);

const USAGE = `Registers the ${LIBRARY.name} MCP server (${LIBRARY.package}) with this project's MCP clients.

  install.mjs                      the clients this project uses; .mcp.json when it shows none
  install.mjs --client <name>      one of ${NAMES.join(', ')}; repeat it, or separate names with commas
  install.mjs --all                every client
  install.mjs --remove             take the entry out instead
  install.mjs --dry-run            say what would change, and write nothing
  install.mjs --print              print the entry, to paste into any other client's config
  install.mjs --help

${NAMES.map((name) => `  ${name.padEnd(8)}${CLIENTS[name].file.padEnd(24)}${CLIENTS[name].label}`).join('\n')}`;

/** The server's entry: npx runs the project's installed copy of the package, or fetches it. */
const entry = (client) => ({ ...client.extra, command: 'npx', args: ['-y', '-p', LIBRARY.package, LIBRARY.bin] });

const isObject = (value) => typeof value === 'object' && value !== null && !Array.isArray(value);

/** The clients asked for, or the ones the project shows signs of, or .mcp.json alone. */
function chosen(values, root) {
  if (values.all) return NAMES;
  const asked = (values.client ?? []).flatMap((value) => value.split(',')).map((name) => name.trim()).filter((name) => name);
  const unknown = asked.find((name) => !NAMES.includes(name));

  if (unknown) throw new Error(`Unknown client ${unknown} (the clients are ${NAMES.join(', ')}).`);

  if (asked.length > 0) return NAMES.filter((name) => asked.includes(name));
  const found = NAMES.filter((name) => CLIENTS[name].signs.some((sign) => existsSync(join(root, sign))));

  return found.length > 0 ? found : ['claude'];
}

/** Adds, updates or removes the entry in one config file. Returns what it did; throws when the file can't be edited safely. */
function apply(client, root, { remove, dryRun }) {
  const path = join(root, client.file);
  const text = existsSync(path) ? readFileSync(path, 'utf8') : undefined;
  let config = {};

  if (text !== undefined && text.trim() !== '') {
    try {
      config = JSON.parse(text);
    } catch {
      throw new Error("isn't plain JSON (comments?)");
    }

    if (!isObject(config)) throw new Error("isn't a JSON object");
  }

  const servers = config[client.key] ?? {};

  if (!isObject(servers)) throw new Error(`"${client.key}" isn't an object`);
  const current = servers[LIBRARY.name];
  const wanted = entry(client);
  let did;

  if (remove) {
    if (current === undefined) return 'not registered';
    delete servers[LIBRARY.name];
    did = 'removed';
  } else {
    if (isDeepStrictEqual(current, wanted)) return 'already registered';
    servers[LIBRARY.name] = wanted;
    did = current === undefined ? 'added' : 'updated';
  }

  config[client.key] = servers;

  if (dryRun) return `would be ${did}`;
  // The file's own indentation, so the diff is the entry alone.
  const indent = text?.match(/^([ \t]+)"/m)?.[1] ?? '  ';

  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, `${JSON.stringify(config, null, indent)}\n`);

  return did;
}

function main(argv) {
  const { values } = parseArgs({
    args: argv,
    options: {
      client: { type: 'string', multiple: true },
      all: { type: 'boolean' },
      remove: { type: 'boolean' },
      'dry-run': { type: 'boolean' },
      print: { type: 'boolean' },
      help: { type: 'boolean', short: 'h' },
    },
  });

  if (values.help) {
    console.log(USAGE);

    return;
  }

  if (values.print) {
    console.log(JSON.stringify({ mcpServers: { [LIBRARY.name]: entry(CLIENTS.claude) } }, null, 2));

    return;
  }

  const root = process.cwd();
  const names = chosen(values, root);
  const width = Math.max(...names.map((name) => CLIENTS[name].file.length));
  let changed = false;

  console.log(`${LIBRARY.name} MCP server (${LIBRARY.package})`);

  for (const name of names) {
    const client = CLIENTS[name];
    let result;

    try {
      result = apply(client, root, { remove: values.remove, dryRun: values['dry-run'] });
      changed ||= ['added', 'updated', 'removed'].includes(result);
    } catch (error) {
      result = `skipped: the file ${error.message}`;

      if (!values.remove) result += `. Add it by hand: "${client.key}": ${JSON.stringify({ [LIBRARY.name]: entry(client) })}`;
      process.exitCode = 1;
    }

    console.log(`  ${client.file.padEnd(width)}  ${result} (${client.label})`);
  }

  if (changed) console.log('Restart the client, or reload its MCP servers, to pick up the change.');
}

try {
  main(process.argv.slice(2));
} catch (error) {
  process.stderr.write(`${error.message}\n\n${USAGE}\n`);
  process.exitCode = 2;
}
